import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        edges = []
        adj = [[] for _ in range(n + 1)]
        in_degree = [0] * (n + 1)

        for i in range(m):
            t_type = int(next(iterator))
            u = int(next(iterator))
            v = int(next(iterator))

            if t_type == 1:
                adj[u].append(v)
                in_degree[v] += 1
            else:
                pass

            edges.append((t_type, u, v))

        q = deque()
        topo_order = {}
        visited = [False] * (n + 1)

        for i in range(1, n + 1):
            if in_degree[i] == 0:
                q.append(i)

        pos = 0
        while q:
            u = q.popleft()
            visited[u] = True
            topo_order[u] = pos
            pos += 1

            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    q.append(v)

        if not all(visited[1:]):
            results.append("NO")
            continue

        results.append("YES")
        for t_type, u, v in edges:
            if t_type == 1:
                results.append(f"{u} {v}")
            else:
                if topo_order[u] < topo_order[v]:
                    results.append(f"{u} {v}")
                else:
                    results.append(f"{v} {u}")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
